{
  "concept": "A polar rectangle R is the region bounded by two constant-r circular arcs and two constant-θ rays — the polar analogue of a Cartesian rectangle, and the basic building block for double integration in polar coordinates.",
  "figureType": "diagram",
  "elements": [
    "Origin (pole) at lower-left corner of the drawing",
    "Solid black horizontal ray from origin to the right representing the polar axis (θ = 0)",
    "Inner circular arc of radius r₁ (solid blue), drawn between the two bounding angles and extending slightly past them",
    "Outer circular arc of radius r₂ (solid blue), drawn between the two bounding angles and extending slightly past them",
    "Lower dashed red ray from origin at angle θ₁, extending beyond the outer arc",
    "Upper dashed red ray from origin at angle θ₂, extending beyond the outer arc",
    "Shaded light-blue curved quadrilateral R bounded by the two arcs and the two rays",
    "Label 'R' centered in the shaded region",
    "Label 'r = 1.5' with leader pointing to the inner arc",
    "Label 'r = 2' with leader pointing to the outer arc",
    "Label 'θ = π/6' near the lower dashed ray",
    "Label 'θ = π/4' near the upper dashed ray",
    "Optional overlay: straight-sided Cartesian rectangle of dimensions Δr × (r̄·Δθ) anchored at the inner corner of R, drawn as a dashed gray/orange outline",
    "Optional annotation of Δr (radial thickness) and Δθ (angular width) as small bracket/arc markers",
    "Optional readout of the exact area A = ½(r₂² − r₁²)(θ₂ − θ₁) versus the approximation r̄ Δr Δθ"
  ],
  "interactions": [
    {
      "id": "innerRadius",
      "type": "slider",
      "teaches": "The inner boundary of R is a curve of constant r — moving it slides a whole circular arc, not a straight line.",
      "label": "Inner radius r₁",
      "range": [0.2, 2.8, 0.05],
      "default": 1.5
    },
    {
      "id": "outerRadius",
      "type": "slider",
      "teaches": "The radial thickness Δr = r₂ − r₁ controls how 'tall' the polar rectangle is in the r-direction while its angular extent is untouched.",
      "label": "Outer radius r₂",
      "range": [0.4, 3.2, 0.05],
      "default": 2.0
    },
    {
      "id": "startAngle",
      "type": "slider",
      "teaches": "The sides of R along constant θ are straight rays from the pole; rotating one sweeps the region without changing its radial bounds.",
      "label": "Start angle θ₁ (radians)",
      "range": [0, 1.4, 0.01],
      "default": 0.5236
    },
    {
      "id": "endAngle",
      "type": "slider",
      "teaches": "Δθ = θ₂ − θ₁ sets the angular width; the arc lengths of the two curved sides differ because arc length r·Δθ grows with r.",
      "label": "End angle θ₂ (radians)",
      "range": [0.05, 1.55, 0.01],
      "default": 0.7854
    },
    {
      "id": "cartesianOverlay",
      "type": "toggle",
      "teaches": "Why R is only an analogue of a rectangle: a straight Δr × r̄Δθ rectangle matches it only when Δr and Δθ are small, which is exactly why dA = r dr dθ and not dr dθ.",
      "label": "Overlay straight rectangle Δr × r̄Δθ",
      "options": ["Polar region only", "Overlay straight rectangle"],
      "default": "Polar region only"
    }
  ],
  "demo_steps": [
    {
      "title": "The textbook polar rectangle",
      "narration": "The region R is trapped between the arcs r = 1.5 and r = 2 and the rays θ = π/6 and θ = π/4. Two of its sides are curved and two are straight.",
      "state": { "innerRadius": 1.5, "outerRadius": 2.0, "startAngle": 0.5236, "endAngle": 0.7854, "cartesianOverlay": "Polar region only" }
    },
    {
      "title": "Change the radial bounds",
      "narration": "Push the outer arc out to r = 3 while the rays stay fixed: R grows only in the radial direction, and the outer curved side becomes noticeably longer than the inner one.",
      "state": { "innerRadius": 1.5, "outerRadius": 3.0, "startAngle": 0.5236, "endAngle": 0.7854, "cartesianOverlay": "Polar region only" }
    },
    {
      "title": "Change the angular bounds",
      "narration": "Now hold r₁ and r₂ fixed and widen the wedge. R sweeps around the pole, keeping the same thickness Δr but covering more angle — and its area grows in proportion to Δθ.",
      "state": { "innerRadius": 1.5, "outerRadius": 3.0, "startAngle": 0.2, "endAngle": 1.2, "cartesianOverlay": "Polar region only" }
    },
    {
      "title": "Compare with a true rectangle",
      "narration": "Overlay a straight-sided rectangle of the same Δr by r̄Δθ dimensions. For this large region the curved sides bow well away from the straight ones — the polar 'rectangle' is not a rectangle.",
      "state": { "innerRadius": 1.5, "outerRadius": 3.0, "startAngle": 0.2, "endAngle": 1.2, "cartesianOverlay": "Overlay straight rectangle" }
    },
    {
      "title": "Shrink it and the mismatch vanishes",
      "narration": "Make Δr and Δθ small: the arcs flatten and the polar rectangle becomes indistinguishable from the straight rectangle of area r̄ Δr Δθ. That limit is exactly the element dA = r dr dθ.",
      "state": { "innerRadius": 1.85, "outerRadius": 2.0, "startAngle": 0.6, "endAngle": 0.68, "cartesianOverlay": "Overlay straight rectangle" }
    }
  ],
  "keyInsight": "A polar rectangle has sides of length Δr and r·Δθ — the second one grows with r — so shrinking it gives the area element dA = r dr dθ rather than the Cartesian dx dy.",
  "reconstructionNotes": "Origin at the lower-left; a solid black polar axis runs horizontally to the right from it. Two dashed red rays emanate from the origin at θ₁ ≈ 30° and θ₂ ≈ 45°, extending past the outer arc. Two solid medium-blue circular arcs centered at the origin at r₁ = 1.5 and r₂ = 2 span slightly beyond both rays. The enclosed curved quadrilateral is filled pale blue with a thin outline and labeled with a serif italic 'R' at its center. Labels in serif math italics: 'r = 1.5' and 'r = 2' placed up and left of the arcs with short leader lines, 'θ = π/4' to the left of the upper ray and 'θ = π/6' below the lower ray, both written as stacked fractions. When the overlay toggle is on, draw a dashed gray-orange straight rectangle anchored at the inner-lower corner of R with width Δr along the mid-ray direction and height r̄Δθ perpendicular to it, plus small labels 'Δr' and 'r̄Δθ' on its sides. Keep the drawing scaled so that r up to ~3.2 stays in frame."
}

