// @FIGURE_CODE_BEGIN
var _cEl = document.getElementById('container');
var dr = SVG().addTo(_cEl).size('100%', '100%');
var FIGW = 700, FIGH = 520;
dr.viewbox(0, 0, FIGW, FIGH);

var FONT = "Georgia,'Times New Roman',Times,serif";
var BLUE = '#1b9ad6', FILLC = '#cbe4f3', RED = '#ef5b68', ORANGE = '#d98a3a', INK = '#111';
var ORG = { x: 58, y: 490 }, SCL = 254, SCLMAX = 254;

var state = { r1: 1.5, r2: 2, t1: 0.5236, t2: 0.7854, overlay: false };

/* ---------- static: polar axis ---------- */
var axisLine = dr.line(14, ORG.y, 678, ORG.y).stroke({ color: INK, width: 3, linecap: 'square' });
var axisHit = dr.line(14, ORG.y, 678, ORG.y).stroke({ color: '#000', width: 16, opacity: 0 }).css('cursor', 'pointer');
axisHit.on('mousemove', function (e) { showTooltip('Polar axis: the ray θ = 0 from the pole', e); })
  .on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('Pole and polar axis', 'Points are addressed by a distance r from the pole (the corner at the left) and an angle θ measured up from this horizontal axis. Curves of constant r are circular arcs; curves of constant θ are straight rays.');
  });

var gDyn = dr.group();

/* ---------- geometry helpers ---------- */
function PT(r, th) { return [ORG.x + r * SCL * Math.cos(th), ORG.y - r * SCL * Math.sin(th)]; }
function fmt(p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }
function trimNum(v) { return String(parseFloat((+v).toFixed(2))); }

function computeScale() {
  var pad = 0.14;
  var aT = Math.min(state.t2 + pad, 1.62), aB = Math.max(state.t1 - pad, 0.015);
  var rOut = state.r2 * 1.06;
  var my = rOut * Math.sin(Math.min(aT, Math.PI / 2));
  var mx = rOut * Math.cos(aB);
  var availY = ORG.y - 58, availX = FIGW - ORG.x - 44;
  return Math.min(SCLMAX, availY / Math.max(my, 0.2), availX / Math.max(mx, 0.2));
}

/* ---------- text helpers ---------- */
function txtEl(p, s, fs, it) {
  return p.text(s).font({ family: FONT, size: fs, style: it ? 'italic' : 'normal', anchor: 'middle', leading: 1 })
    .fill(INK).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
}
function mathLabel(parent, spec, x, y, anchor, fs) {
  fs = fs || 19;
  var grp = parent.group(), cur = 0;
  spec.forEach(function (s) {
    if (s.frac) {
      var n = txtEl(grp, s.frac[0], fs, true), d2 = txtEl(grp, s.frac[1], fs, false);
      var w = Math.max(n.bbox().width, d2.bbox().width) + 2;
      n.cx(cur + w / 2).cy(-fs * 0.62);
      d2.cx(cur + w / 2).cy(fs * 0.66);
      grp.line(cur, 0, cur + w, 0).stroke({ color: INK, width: 1.6 });
      cur += w + 4;
    } else {
      var t = txtEl(grp, s.t, fs, s.i);
      var w2 = t.bbox().width;
      t.cx(cur + w2 / 2).cy(0);
      if (s.over) grp.line(cur + 2, -fs * 0.66, cur + w2 - 2, -fs * 0.66).stroke({ color: INK, width: 1.4 });
      cur += w2 + (s.g == null ? 4 : s.g);
    }
  });
  var b = grp.bbox();
  var dx = anchor === 'end' ? x - (b.x + b.width) : (anchor === 'middle' ? x - (b.x + b.width / 2) : x - b.x);
  grp.transform({ translate: [dx, y - (b.y + b.height / 2)] });
  return grp;
}
function angleSpec(th) {
  var dens = [2, 3, 4, 5, 6, 8, 10, 12];
  for (var i = 0; i < dens.length; i++) {
    var d = dens[i];
    for (var k = 1; k < d; k++) {
      if (Math.abs(th - k * Math.PI / d) < 0.013) {
        return [{ frac: [(k === 1 ? 'π' : k + 'π'), String(d)] }];
      }
    }
  }
  return [{ t: th.toFixed(2) }];
}

/* ---------- drawing ---------- */
function arcEl(r, a0, a1, color, w) {
  var p0 = PT(r, a0), p1 = PT(r, a1), rp = (r * SCL).toFixed(2);
  return gDyn.path('M' + fmt(p0) + ' A' + rp + ',' + rp + ' 0 0 0 ' + fmt(p1))
    .fill('none').stroke({ color: color, width: w, linecap: 'round' });
}
function rayEnd(th) {
  var dx = Math.cos(th), dy = -Math.sin(th);
  var L = state.r2 * SCL * 1.24 + 26;
  if (dx > 1e-6) L = Math.min(L, (FIGW - 14 - ORG.x) / dx);
  if (dy < -1e-6) L = Math.min(L, (ORG.y - 14) / (-dy));
  return [ORG.x + dx * L, ORG.y + dy * L];
}

function redraw() {
  SCL = computeScale();
  gDyn.clear();
  var r1 = state.r1, r2 = state.r2, t1 = state.t1, t2 = state.t2;
  var rm = (r1 + r2) / 2, tm = (t1 + t2) / 2, dR = r2 - r1, dT = t2 - t1;
  var pad = 0.14;
  var aT = Math.min(t2 + pad, 1.62), aB = Math.max(t1 - pad, 0.015);

  /* shaded polar rectangle */
  var pA = PT(r1, t1), pB = PT(r1, t2), pC = PT(r2, t2), pD = PT(r2, t1);
  var dpath = 'M' + fmt(pA) + ' A' + (r1 * SCL).toFixed(2) + ',' + (r1 * SCL).toFixed(2) + ' 0 0 0 ' + fmt(pB) +
    ' L' + fmt(pC) + ' A' + (r2 * SCL).toFixed(2) + ',' + (r2 * SCL).toFixed(2) + ' 0 0 1 ' + fmt(pD) + ' Z';
  var region = gDyn.path(dpath).fill(FILLC).stroke({ color: '#8cc4e2', width: 0.8 }).css('cursor', 'pointer');
  region.on('mousemove', function (e) {
    showTooltip('Polar rectangle R: ' + trimNum(r1) + ' ≤ r ≤ ' + trimNum(r2) + ',  ' + t1.toFixed(2) + ' ≤ θ ≤ ' + t2.toFixed(2) +
