dr.viewbox(0, 0, FIGW, FIGH);

var FONT = "Georgia,'Times New Roman',Times,serif";
var BLUE = '#1b9ad6', FILLC = '#cbe4f3', RED = '#ef5b68', ORANGE = '#d98a3a', INK = '#111';
var ORG = { x: 58, y: 490 }, SCL = 254, SCLMAX = 254;

var state = { r1: 1.5, r2: 2, t1: 0.5236, t2: 0.7854, overlay: false };

/* ---------- static: polar axis ---------- */
var axisLine = dr.line(14, ORG.y, 678, ORG.y).stroke({ color: INK, width: 3, linecap: 'square' });
var axisHit = dr.line(14, ORG.y, 678, ORG.y).stroke({ color: '#000', width: 16, opacity: 0 }).css('cursor', 'pointer');
axisHit.on('mousemove', function (e) { showTooltip('Polar axis: the ray θ = 0 from the pole', e); })
  .on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('Pole and polar axis', 'Points are addressed by a distance r from the pole (the corner at the left) and an angle θ measured up from this horizontal axis. Curves of constant r are circular arcs; curves of constant θ are straight rays.');
  });

var gDyn = dr.group();

/* ---------- geometry helpers ---------- */
function PT(r, th) { return [ORG.x + r * SCL * Math.cos(th), ORG.y - r * SCL * Math.sin(th)]; }
function fmt(p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }
function trimNum(v) { return String(parseFloat((+v).toFixed(2))); }

function computeScale() {
  var pad = 0.14;
  var aT = Math.min(state.t2 + pad, 1.62), aB = Math.max(state.t1 - pad, 0.015);
  var rOut = state.r2 * 1.06;
  var my = rOut * Math.sin(Math.min(aT, Math.PI / 2));
  var mx = rOut * Math.cos(aB);
  var availY = ORG.y - 58, availX = FIGW - ORG.x - 44;
  return Math.min(SCLMAX, availY / Math.max(my, 0.2), availX / Math.max(mx, 0.2));
}

/* ---------- text helpers ---------- */
function txtEl(p, s, fs, it) {
  return p.text(s).font({ family: FONT, size: fs, style: it ? 'italic' : 'normal', anchor: 'middle', leading: 1 })
    .fill(INK).attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
}
function mathLabel(parent, spec, x, y, anchor, fs) {
  fs = fs || 19;
  var grp = parent.group(), cur = 0;
  spec.forEach(function (s) {
    if (s.frac) {
      var n = txtEl(grp, s.frac[0], fs, true), d2 = txtEl(grp, s.frac[1], fs, false);
      var w = Math.max(n.bbox().width, d2.bbox().width) + 2;
      n.cx(cur + w / 2).cy(-fs * 0.62);
      d2.cx(cur + w / 2).cy(fs * 0.66);
      grp.line(cur, 0, cur + w, 0).stroke({ color: INK, width: 1.6 });
      cur += w + 4;
    } else {
      var t = txtEl(grp, s.t, fs, s.i);
      var w2 = t.bbox().width;
      t.cx(cur + w2 / 2).cy(0);
      if (s.over) grp.line(cur + 2, -fs * 0.66, cur + w2 - 2, -fs * 0.66).stroke({ color: INK, width: 1.4 });
      cur += w2 + (s.g == null ? 4 : s.g);
    }
  });
  var b = grp.bbox();
  var dx = anchor === 'end' ? x - (b.x + b.width) : (anchor === 'middle' ? x - (b.x + b.width / 2) : x - b.x);
  grp.transform({ translate: [dx, y - (b.y + b.height / 2)] });
  return grp;
}
function angleSpec(th) {
  var dens = [2, 3, 4, 5, 6, 8, 10, 12];
  for (var i = 0; i < dens.length; i++) {
    var d = dens[i];
    for (var k = 1; k < d; k++) {
      if (Math.abs(th - k * Math.PI / d) < 0.013) {
        return [{ frac: [(k === 1 ? 'π' : k + 'π'), String(d)] }];
      }
    }
  }
  return [{ t: th.toFixed(2) }];
}

/* ---------- drawing ---------- */
function arcEl(r, a0, a1, color, w) {
  var p0 = PT(r, a0), p1 = PT(r, a1), rp = (r * SCL).toFixed(2);
  return gDyn.path('M' + fmt(p0) + ' A' + rp + ',' + rp + ' 0 0 0 ' + fmt(p1))
    .fill('none').stroke({ color: color, width: w, linecap: 'round' });
}
function rayEnd(th) {
  var dx = Math.cos(th), dy = -Math.sin(th);
  var L = state.r2 * SCL * 1.24 + 26;
  if (dx > 1e-6) L = Math.min(L, (FIGW - 14 - ORG.x) / dx);
  if (dy < -1e-6) L = Math.min(L, (ORG.y - 14) / (-dy));
  return [ORG.x + dx * L, ORG.y + dy * L];
}

function redraw() {
  SCL = computeScale();
  gDyn.clear();
  var r1 = state.r1, r2 = state.r2, t1 = state.t1, t2 = state.t2;
  var rm = (r1 + r2) / 2, tm = (t1 + t2) / 2, dR = r2 - r1, dT = t2 - t1;
  var pad = 0.14;
  var aT = Math.min(t2 + pad, 1.62), aB = Math.max(t1 - pad, 0.015);

  /* shaded polar rectangle */
  var pA = PT(r1, t1), pB = PT(r1, t2), pC = PT(r2, t2), pD = PT(r2, t1);
  var dpath = 'M' + fmt(pA) + ' A' + (r1 * SCL).toFixed(2) + ',' + (r1 * SCL).toFixed(2) + ' 0 0 0 ' + fmt(pB) +
    ' L' + fmt(pC) + ' A' + (r2 * SCL).toFixed(2) + ',' + (r2 * SCL).toFixed(2) + ' 0 0 1 ' + fmt(pD) + ' Z';
  var region = gDyn.path(dpath).fill(FILLC).stroke({ color: '#8cc4e2', width: 0.8 }).css('cursor', 'pointer');
  region.on('mousemove', function (e) {
    showTooltip('Polar rectangle R: ' + trimNum(r1) + ' ≤ r ≤ ' + trimNum(r2) + ',  ' + t1.toFixed(2) + ' ≤ θ ≤ ' + t2.toFixed(2) +
      '   area = ' + (0.5 * (r2 * r2 - r1 * r1) * dT).toFixed(3), e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('The polar rectangle R', 'R = { (r,θ) : r₁ ≤ r ≤ r₂, θ₁ ≤ θ ≤ θ₂ }. Its two radial sides have length Δr, but its two curved sides have lengths r₁Δθ and r₂Δθ — different, because arc length grows with r. Its exact area is ½(r₂²−r₁²)Δθ = r̄ Δr Δθ, and shrinking it gives dA = r dr dθ.');
  });

  /* dashed rays θ = θ₁, θ = θ₂ */
  [t1, t2].forEach(function (th, i) {
    var e2 = rayEnd(th);
    gDyn.line(ORG.x, ORG.y, e2[0], e2[1]).stroke({ color: RED, width: 2, dasharray: '11,8' });
    gDyn.line(ORG.x, ORG.y, e2[0], e2[1]).stroke({ color: RED, width: 14, opacity: 0 }).css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip('Constant-θ side: θ = ' + th.toFixed(3) + ' rad — a straight ray from the pole', ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('A side of constant θ', 'Holding θ fixed and letting r run from r₁ to r₂ traces a straight segment of length Δr = r₂ − r₁. These are the two "straight" sides of the polar rectangle.');
      });
  });

  /* blue arcs r = r₁, r = r₂ */
  [[r1, 'inner'], [r2, 'outer']].forEach(function (a) {
    var el = arcEl(a[0], aB, aT, BLUE, 4.5).css('cursor', 'pointer');
    el.on('mousemove', function (ev) {
      showTooltip('Constant-r side: r = ' + trimNum(a[0]) + ' — circular arc, length r·Δθ = ' + (a[0] * dT).toFixed(2), ev);
    }).on('mouseleave', hideTooltip).on('click', function () {
      showPopup('A side of constant r', 'Holding r fixed and letting θ run from θ₁ to θ₂ traces a circular arc of length r·Δθ. Because this length is proportional to r, the outer side is always longer than the inner one — the source of the extra factor r in dA = r dr dθ.');
    });
  });

  /* straight-rectangle overlay */
  if (state.overlay) {
    var C = PT(rm, tm);
    var u = [Math.cos(tm), -Math.sin(tm)], v = [-Math.sin(tm), -Math.cos(tm)];
    var hr = dR * SCL / 2, ht = rm * dT * SCL / 2;
    var cs = [[1, 1], [1, -1], [-1, -1], [-1, 1]].map(function (s) {
      return [C[0] + s[0] * hr * u[0] + s[1] * ht * v[0], C[1] + s[0] * hr * u[1] + s[1] * ht * v[1]];
    });
    var poly = gDyn.polygon(cs.map(function (p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' '))
      .fill({ color: ORANGE, opacity: 0.08 }).stroke({ color: ORANGE, width: 2, dasharray: '7,5' }).css('cursor', 'pointer');
    poly.on('mousemove', function (ev) {
      showTooltip('Straight rectangle Δr × r̄Δθ = ' + dR.toFixed(2) + ' × ' + (rm * dT).toFixed(2) + ' — area ' + (rm * dR * dT).toFixed(3), ev);
    }).on('mouseleave', hideTooltip).on('click', function () {
      showPopup('Is it really a rectangle?', 'The dashed straight rectangle has sides Δr and r̄Δθ, so its area r̄ΔrΔθ equals the exact area of R. Its shape only matches R when Δr and Δθ are small: the arcs bow away by about r(1 − cos(Δθ/2)). In the limit the two coincide, giving dA = r dr dθ.');
    });
    var lr = [C[0] - (ht + 15) * v[0], C[1] - (ht + 15) * v[1]];
    mathLabel(gDyn, [{ t: 'Δ', g: 0 }, { t: 'r', i: true }], lr[0], lr[1], 'middle', 16).fill(ORANGE);
    var lt = [C[0] + (hr + 19) * u[0], C[1] + (hr + 19) * u[1]];
    mathLabel(gDyn, [{ t: 'r', i: true, over: true, g: 2 }, { t: 'Δ', g: 0 }, { t: 'θ', i: true }], lt[0], lt[1], 'middle', 16).fill(ORANGE);
  }

  /* r = ... labels with leaders */
  var uT = [Math.cos(aT), -Math.sin(aT)], tgT = [-Math.sin(aT), -Math.cos(aT)];
  function rLabel(r, back) {
    var ap = PT(r, aT);
    var lp = [ap[0] + 54 * tgT[0] - back * uT[0], ap[1] + 54 * tgT[1] - back * uT[1]];
    gDyn.line(ap[0] + 9 * tgT[0], ap[1] + 9 * tgT[1], lp[0] - 5 * tgT[0], lp[1] - 5 * tgT[1]).stroke({ color: '#666', width: 1 });
    mathLabel(gDyn, [{ t: 'r', i: true }, { t: '=' }, { t: trimNum(r) }], lp[0] - 7, lp[1], 'end', 19);
  }
  rLabel(r2, 0);
  rLabel(r1, Math.max(0, 46 - dR * SCL));

  /* θ = ... labels */
  function thetaLabel(th, radFrac, side) {
    var A = PT(Math.max(radFrac * r2, 0.42), th);
    var n = side > 0 ? [-Math.sin(th), -Math.cos(th)] : [Math.sin(th), Math.cos(th)];
    var lx = A[0] + 34 * n[0], ly = A[1] + 34 * n[1];
    ly = Math.min(ly, ORG.y - 36);
    mathLabel(gDyn, [{ t: 'θ', i: true }, { t: '=' }].concat(angleSpec(th)), lx, ly, side > 0 ? 'end' : 'start', 19);
  }
  thetaLabel(t2, 0.50, 1);
  thetaLabel(t1, 0.74, -1);

  /* R label */
  var Cc = PT(rm, tm), vv = [-Math.sin(tm), -Math.cos(tm)];
  var minDim = Math.min(dR * SCL, rm * dT * SCL);
  var Rp = Cc;
  if (minDim < 38) {
    var off = rm * dT * SCL / 2 + 32;
    Rp = [Cc[0] + off * vv[0], Cc[1] + off * vv[1]];
    gDyn.line(Cc[0], Cc[1], Rp[0], Rp[1]).stroke({ color: '#666', width: 1 });
  }
  mathLabel(gDyn, [{ t: 'R', i: true }], Rp[0], Rp[1], 'middle', 24);

  updateReadout();
}

/* ---------- readout ---------- */
function updateReadout() {
  var r1 = state.r1, r2 = state.r2, dT = state.t2 - state.t1, rm = (r1 + r2) / 2, dR = r2 - r1;
  var area = 0.5 * (r2 * r2 - r1 * r1) * dT;
  var bow = r2 * (1 - Math.cos(dT / 2));
  var el = document.getElementById('areaOut');
  if (!el) return;
  el.innerHTML =
    'Δr = <b>' + dR.toFixed(2) + '</b> &nbsp; Δθ = <b>' + dT.toFixed(2) + '</b> rad<br>' +
    'inner arc r₁Δθ = ' + (r1 * dT).toFixed(2) + ' &nbsp; outer arc r₂Δθ = ' + (r2 * dT).toFixed(2) + '<br>' +
    'area ½(r₂²−r₁²)Δθ = <b>' + area.toFixed(4) + '</b><br>' +
    'r̄ Δr Δθ = <b>' + (rm * dR * dT).toFixed(4) + '</b> (same!)<br>' +
    'arc bow r₂(1−cos(Δθ/2)) = ' + bow.toFixed(3) +
    ' &nbsp;(' + (100 * bow / Math.max(dR, 1e-6)).toFixed(0) + '% of Δr)';
}

/* ---------- controls ---------- */
function setCtl(id, v, dp) {
  var i = document.getElementById(id + 'Input'); if (i) i.value = v;
  var o = document.getElementById(id + 'Val'); if (o) o.value = (+v).toFixed(dp);
}
function update_innerRadius(v) {
  state.r1 = +v;
  if (state.r1 > state.r2 - 0.1) { state.r2 = Math.min(3.2, state.r1 + 0.1); setCtl('outerRadius', state.r2, 2); }
  setCtl('innerRadius', state.r1, 2);
  redraw();
}
function update_outerRadius(v) {
  state.r2 = +v;
  if (state.r2 < state.r1 + 0.1) { state.r1 = Math.max(0.2, state.r2 - 0.1); setCtl('innerRadius', state.r1, 2); }
  setCtl('outerRadius', state.r2, 2);
  redraw();
}
function update_startAngle(v) {
  state.t1 = +v;
  if (state.t1 > state.t2 - 0.05) { state.t2 = Math.min(1.55, state.t1 + 0.05); setCtl('endAngle', state.t2, 3); }
  setCtl('startAngle', state.t1, 3);
  redraw();
}
function update_endAngle(v) {
  state.t2 = +v;
  if (state.t2 < state.t1 + 0.05) { state.t1 = Math.max(0, state.t2 - 0.05); setCtl('startAngle', state.t1, 3); }
  setCtl('endAngle', state.t2, 3);
  redraw();
}
function toggle_cartesianOverlay(on) { state.overlay = !!on; redraw(); }

/* ---------- demo player ---------- */
var STEPS = [
  { title: 'The textbook polar rectangle', narration: 'R is trapped between the arcs r = 1.5 and r = 2 and the rays θ = π/6 and θ = π/4. Two of its sides are curved, two are straight.', s: { r1: 1.5, r2: 2, t1: 0.5236, t2: 0.7854, ov: false } },
  { title: 'Change the radial bounds', narration: 'Push the outer arc out to r = 3 with the rays fixed: R grows only in the radial direction, and the outer curved side becomes noticeably longer than the inner one.', s: { r1: 1.5, r2: 3, t1: 0.5236, t2: 0.7854, ov: false } },
  { title: 'Change the angular bounds', narration: 'Now hold r₁ and r₂ and widen the wedge. R keeps the same thickness Δr but covers more angle — and its area grows in proportion to Δθ.', s: { r1: 1.5, r2: 3, t1: 0.2, t2: 1.2, ov: false } },
  { title: 'Compare with a true rectangle', narration: 'Overlay a straight rectangle with the same Δr by r̄Δθ dimensions. For this large region the curved sides bow well away from the straight ones — the polar "rectangle" is not a rectangle.', s: { r1: 1.5, r2: 3, t1: 0.2, t2: 1.2, ov: true } },
  { title: 'Shrink it and the mismatch vanishes', narration: 'Make Δr and Δθ small: the arcs flatten and R becomes indistinguishable from the straight rectangle of area r̄ Δr Δθ. That limit is exactly dA = r dr dθ.', s: { r1: 1.85, r2: 2, t1: 0.6, t2: 0.68, ov: true } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i % STEPS.length + STEPS.length) % STEPS.length;
  var st = STEPS[stepIdx];
  state.r1 = st.s.r1; state.r2 = st.s.r2; state.t1 = st.s.t1; state.t2 = st.s.t2; state.overlay = st.s.ov;
  setCtl('innerRadius', state.r1, 2); setCtl('outerRadius', state.r2, 2);
  setCtl('startAngle', state.t1, 3); setCtl('endAngle', state.t2, 3);
  var cb = document.getElementById('cartesianOverlayInput'); if (cb) cb.checked = state.overlay;
  var n = document.getElementById('demoNarration');
  if (n) n.innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
  redraw();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
